{"command": "cd /home/daytona && python -c "
from daytona import Daytona, DaytonaConfig
import os

d = Daytona(DaytonaConfig(api_key=os.environ.get('DAYTONA_API_KEY')))
try:
    result = d.list()
    print(f'Total sandboxes: {result.total}')
    for s in result.items:
        print(f'  Sandbox: {s.id}, State: {s.state}')
except Exception as e:
    print(f'Error: {type(e).__name__}: {e}')
""}

